package com.ruoyi.metal.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import org.mockito.MockedStatic;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.dao.DuplicateKeyException;import com.ruoyi.common.utils.SecurityUtils;import com.ruoyi.common.utils.PasswordPolicy;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.metal.security.FactoryScope;
class ProfileManagementServiceTest{
 JdbcTemplate jdbc;FactoryScope scope;ProfileManagementService service;MockedStatic<SecurityUtils> security;
 @BeforeEach void setUp(){jdbc=mock(JdbcTemplate.class);scope=mock(FactoryScope.class);service=new ProfileManagementService(jdbc,scope);security=mockStatic(SecurityUtils.class);security.when(SecurityUtils::getUserId).thenReturn(8L);security.when(SecurityUtils::getUsername).thenReturn("18800000001");security.when(()->SecurityUtils.isAdmin(8L)).thenReturn(false);security.when(()->SecurityUtils.matchesPassword("old","hash")).thenReturn(true);security.when(()->SecurityUtils.encryptPassword("New123456")).thenReturn("new-hash");when(jdbc.queryForMap(anyString(),any(Object[].class))).thenReturn(new LinkedHashMap<>(Map.of("factory_id",3L,"version",2,"password","hash","phonenumber","18800000001")));when(jdbc.update(anyString(),any(Object[].class))).thenReturn(1);}
 @AfterEach void close(){security.close();}
 @Test void passwordChangesInvalidateAllSessions(){service.password(new ProfileManagementService.Password("old","New123456"));verify(scope).invalidate(List.of(8L));verify(jdbc).update(contains("pwd_update_date=NOW(),version=version+1"),eq("new-hash"),eq("18800000001"),eq(8L));}
 @Test void invalidOrWrongPasswordsNeverUpdate(){assertThrows(ServiceException.class,()->service.password(new ProfileManagementService.Password("old","short")));assertThrows(ServiceException.class,()->service.password(new ProfileManagementService.Password("wrong","New123456")));verify(jdbc,never()).update(anyString(),any(Object[].class));verify(scope,never()).invalidate(anyCollection());}
 @Test void phoneChangesUsernameAndRequestsRelogin(){assertTrue(service.update(new ProfileManagementService.Profile(2,"名字","18800000002",null,"0")));verify(jdbc).update(contains("user_name=?"),eq("名字"),eq("18800000002"),eq("18800000002"),isNull(),eq("0"),eq("18800000001"),eq(8L),eq(2));verify(scope).invalidate(List.of(8L));}
 @Test void ordinaryDetailsDoNotRevokeSessions(){assertFalse(service.update(new ProfileManagementService.Profile(2,"新名字","18800000001",null,"0")));verify(scope,never()).invalidate(anyCollection());}
 @Test void staleVersionAndDuplicatePhoneDoNotRevokeSessions(){assertThrows(ServiceException.class,()->service.update(new ProfileManagementService.Profile(1,"名字","18800000002",null,"0")));when(jdbc.update(anyString(),any(Object[].class))).thenThrow(new DuplicateKeyException("duplicate"));assertThrows(ServiceException.class,()->service.update(new ProfileManagementService.Profile(2,"名字","18800000002",null,"0")));verify(scope,never()).invalidate(anyCollection());}
 @Test void adminUsernameRemainsAdmin(){security.when(SecurityUtils::getUserId).thenReturn(1L);security.when(()->SecurityUtils.isAdmin(1L)).thenReturn(true);assertFalse(service.update(new ProfileManagementService.Profile(2,"管理员","18800000002",null,"0")));verify(jdbc).update(contains("user_name=?"),eq("管理员"),eq("18800000002"),eq("admin"),isNull(),eq("0"),anyString(),eq(1L),eq(2));verify(scope,never()).invalidate(anyCollection());}
 @Test void passwordPolicyUsesUtf8BytesAndPreservesSpaces(){assertFalse(PasswordPolicy.valid(null));assertFalse(PasswordPolicy.valid("1234567"));assertFalse(PasswordPolicy.valid("        "));assertTrue(PasswordPolicy.valid("12345678"));assertTrue(PasswordPolicy.valid("汉".repeat(24)));assertFalse(PasswordPolicy.valid("汉".repeat(25)));assertTrue(PasswordPolicy.valid(" pass123 "));}
}
